import * as React from "react";
import { useEffect } from "react";
import Link from "./AppLink";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "./Layout";
import SEO from "./seo";
import I18nHeadProvider from "./I18nHeadProvider";
import type {
  I18nPageContext,
  LocaleQueryData,
} from "./I18nHeadProvider";
import ContactForm from "./contactForm";
import CaseStudyProofGrid, {
  type CaseStudyProofItem,
  type CaseStudyProofLabels,
} from "./CaseStudyProofGrid";
import data from "../data/data.json";
import images from "../images";
import type { Company } from "../interfaces";
import { buildContactIntentPath } from "../utils/cta";
import { getCaseStudyProofSource } from "../utils/caseStudyProof";
import {
  buildBreadcrumbListSchema,
  localizeSitePath,
} from "../utils/structuredData";
import {
  getVerticalConfig,
  type VerticalKey,
} from "../utils/verticals";

const info: Company = data[0];

type SectionItem = {
  eyebrow?: string;
  title: string;
  text?: string;
  bullets?: Array<{ item: string }>;
};

type Props = {
  verticalKey: VerticalKey;
};

export const VerticalLandingPage: React.FC<Props> = ({ verticalKey }) => {
  const { t } = useTranslation();
  const config = getVerticalConfig(verticalKey);
  const root = config.translationRoot;

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const sectionsRaw = t(`${root}.sections`, {
    returnObjects: true,
    defaultValue: [],
  }) as unknown;
  const sections = Array.isArray(sectionsRaw) ? (sectionsRaw as SectionItem[]) : [];
  const proofLabels = t("proofBlocks.labels", {
    returnObjects: true,
  }) as CaseStudyProofLabels;
  const proofCtaLabel = t("proofBlocks.ctaLabel") as string;
  const proofSource = getCaseStudyProofSource(t, config.proofSlug);
  const proofItems: CaseStudyProofItem[] = [
    {
      client: proofSource.client,
      businessType: proofSource.businessType,
      problem: proofSource.challenges[0] || "",
      intervention:
        proofSource.interventions[0] ||
        proofSource.interventions[1] ||
        "",
      result:
        proofSource.results[0] ||
        proofSource.metrics[0]?.value ||
        "",
      href: proofSource.href,
      ctaLabel: proofCtaLabel,
    },
  ].filter(
    (item) =>
      item.client &&
      item.businessType &&
      item.problem &&
      item.intervention &&
      item.result
  );

  return (
    <Layout data={info}>
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <p className="uppercase tracking-[0.2em] text-xs text-verde">
              {t(`${root}.hero.kicker`)}
            </p>
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-5xl mt-3">
              {t(`${root}.hero.title`)}
            </h1>
            <p className="mt-4 text-lg sm:text-xl text-light/85 mx-auto max-w-4xl">
              {t(`${root}.hero.subtitle`)}
            </p>

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to={buildContactIntentPath("strategicReview")}
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t(`${root}.hero.primaryCta`)}
              </Link>
              <a
                href={buildContactIntentPath("strategicReview")}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
              >
                {t(`${root}.hero.secondaryCta`)}
              </a>
            </div>
          </div>
        </div>
      </section>

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {sections.map((section, index) => (
              <article key={`${section.title}-${index}`} className={styles.card}>
                {section.eyebrow ? (
                  <p className="uppercase tracking-[0.2em] text-xs text-verde">
                    {section.eyebrow}
                  </p>
                ) : null}
                <h2 className="mt-2 text-xl font-semibold text-light">
                  {section.title}
                </h2>
                {section.text ? (
                  <p className="mt-3 text-light/80 leading-relaxed">
                    {section.text}
                  </p>
                ) : null}
                {Array.isArray(section.bullets) && section.bullets.length > 0 ? (
                  <ul className="mt-4 list-disc pl-6 space-y-2 text-light/75">
                    {section.bullets.map((bullet, bulletIndex) => (
                      <li key={`${section.title}-${bullet.item}-${bulletIndex}`}>
                        {bullet.item}
                      </li>
                    ))}
                  </ul>
                ) : null}
              </article>
            ))}
          </div>
        </div>
      </section>

      <section className="py-4 sm:py-8">
        <div className={styles.container}>
          <article className={styles.card}>
            <p className="uppercase tracking-[0.2em] text-xs text-verde text-center">
              {t(`${root}.recommendedServices.eyebrow`)}
            </p>
            <h2 className="mt-2 text-2xl sm:text-3xl poppins-regular text-verde text-center">
              {t(`${root}.recommendedServices.title`)}
            </h2>
            <p className="mt-4 max-w-3xl mx-auto text-center text-light/80">
              {t(`${root}.recommendedServices.subtitle`)}
            </p>
            <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
              {config.recommendedServices.map((serviceKey) => (
                <Link
                  key={serviceKey}
                  to={`/services/${
                    serviceKey === "webDesignDevelopment"
                      ? "web-design-development"
                      : serviceKey === "aiSearchOptimization"
                        ? "ai-search-optimization"
                        : serviceKey
                  }/`}
                  className="rounded-full border border-white/15 bg-white/10 px-4 py-2 text-sm text-light/90"
                >
                  {t(`menu.services.${serviceKey}.nav`) as string}
                </Link>
              ))}
            </div>
          </article>
        </div>
      </section>

      <CaseStudyProofGrid
        title={t(`${root}.proof.title`) as string}
        subtitle={t(`${root}.proof.subtitle`) as string}
        labels={proofLabels}
        items={proofItems}
      />

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <article className={styles.card}>
            <h2 className="text-2xl sm:text-3xl poppins-regular text-verde text-center">
              {t(`${root}.form.title`)}
            </h2>
            <div className="mt-8 flex justify-center">
              <ContactForm
                leadIntent="strategicReview"
                intro={t(`${root}.form.subtitle`) as string}
                submitLabel={
                  (t("journeyCtas.types.strategicReview.submitLabel") as string)
                }
              />
            </div>
          </article>
        </div>
      </section>
    </Layout>
  );
};

export const VerticalLandingHead: React.FC<Props> = ({ verticalKey }) => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();
  const config = getVerticalConfig(verticalKey);
  const root = config.translationRoot;

  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t(`${root}.navLabel`) as string,
      path: localizeSitePath(config.path, language, defaultLanguage),
    },
  ]);

  return (
    <SEO
      data={info}
      titleKey={`${root}.metaTitle`}
      descriptionKey={`${root}.metaDescription`}
      pathname={config.path}
      schemaType="ProfessionalService"
      pageSchemaType="Service"
      additionalSchemas={breadcrumbSchema ? [breadcrumbSchema] : undefined}
    />
  );
};

export const VerticalLandingHeadProvider: React.FC<
  Props & { data?: LocaleQueryData; pageContext?: I18nPageContext }
> = ({ verticalKey, data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <VerticalLandingHead verticalKey={verticalKey} />
  </I18nHeadProvider>
);

const styles = {
  container: "w-full max-w-6xl mx-auto px-4 sm:px-6",
  card: "rounded-3xl border border-white/15 bg-white/5 p-6",
};
